<script>
  import { onMount } from 'svelte';
  import { projectStore, materialStore, uiStore, authStore } from '../stores/index.js';
  import { 
    materialsApi, 
    inboundRecordsApi, 
    outboundRecordsApi,
    categoriesApi 
  } from '../services/database.js';
  import { canInbound, canOutbound, canCreateProject, isAdmin, canEditInbound, canEditOutbound } from '../constants/roles.js';
  import DataTable from '../components/DataTable.svelte';
  import * as XLSX from 'xlsx';

  export let params = {};

  let projectId = null;
  let viewType = null;
  let categoryId = null;
  let project = null;
  let category = null;
  let materials = [];
  let records = [];
  let categorySummary = [];  // 分类汇总数据
  let isLoading = true;
  let role = null;

  // Form state
  let showAddForm = false;
  let formData = {
    name: '',
    specification: '',
    material_type: '',
    description: '',
    unit: '',
    quantity: 0,
    date: new Date().toISOString().split('T')[0],
    batch_no: '',
    remarks: ''
  };

  // Edit modal state
  let showEditModal = false;
  let editingRecord = null;
  let editFormData = {
    quantity: 0,
    date: '',
    batch_no: '',
    remarks: ''
  };

  // Rename category state
  let showRenameModal = false;
  let renamingCategory = null;
  let newCategoryNameInput = '';

  // Pagination state (for detail pages)
  let currentPage = 1;
  let pageSize = 20;
  const pageSizeOptions = [10, 20, 50, 100];

  // Summary table pagination (per category)
  let summaryPageMap = {};  // { categoryId: currentPage }
  // 汇总表也使用 pageSize，保持一致

  // Sorting state (for detail pages)
  let sortKey = null;
  let sortDirection = 'asc';  // 'asc' or 'desc'
  const sortableFields = ['name', 'specification', 'material_type', 'description'];

  // Summary table sorting (per category)
  let summarySortMap = {};  // { categoryId: { key, direction } }
  let summaryVersion = 0;  // 用于强制响应式更新

  // 排序函数
  function sortData(data, key, direction) {
    if (!key) return data;
    return [...data].sort((a, b) => {
      const valA = (a[key] || '').toString().toLowerCase();
      const valB = (b[key] || '').toString().toLowerCase();
      if (valA < valB) return direction === 'asc' ? -1 : 1;
      if (valA > valB) return direction === 'asc' ? 1 : -1;
      return 0;
    });
  }

  // 搜索过滤状态
  let searchFilters = {
    name: '',
    specification: '',
    material_type: '',
    description: '',
    unit: '',
    quantity: '',
    date: '',         // arrival_date 或 outbound_date
    batch_no: '',     // batch_no 或 outbound_no
    remarks: ''
  };
  let activeFilters = {};  // 当前生效的过滤条件

  // 重置搜索条件
  function resetSearchFilters() {
    searchFilters = {
      name: '',
      specification: '',
      material_type: '',
      description: '',
      unit: '',
      quantity: '',
      date: '',
      batch_no: '',
      remarks: ''
    };
    activeFilters = {};
    currentPage = 1;
  }

  // 应用搜索过滤
  function applySearch() {
    activeFilters = { ...searchFilters };
    currentPage = 1;
  }

  // 过滤数据
  function filterData(data, filters) {
    if (Object.values(filters).every(v => !v)) return data;
    
    return data.filter(item => {
      // 名称过滤
      if (filters.name && !String(item.name || '').toLowerCase().includes(filters.name.toLowerCase())) {
        return false;
      }
      // 规格型号过滤
      if (filters.specification && !String(item.specification || '').toLowerCase().includes(filters.specification.toLowerCase())) {
        return false;
      }
      // 材质过滤
      if (filters.material_type && !String(item.material_type || '').toLowerCase().includes(filters.material_type.toLowerCase())) {
        return false;
      }
      // 材料描述过滤
      if (filters.description && !String(item.description || '').toLowerCase().includes(filters.description.toLowerCase())) {
        return false;
      }
      // 单位过滤
      if (filters.unit && !String(item.unit || '').toLowerCase().includes(filters.unit.toLowerCase())) {
        return false;
      }
      // 数量过滤（精确匹配或范围）
      if (filters.quantity) {
        const qty = item.quantity || item.total_inbound || item.total_outbound || 0;
        if (!String(qty).includes(filters.quantity)) {
          return false;
        }
      }
      // 日期过滤
      if (filters.date) {
        const dateField = item.arrival_date || item.outbound_date || '';
        if (!String(dateField).includes(filters.date)) {
          return false;
        }
      }
      // 单号过滤
      if (filters.batch_no) {
        const batchField = item.batch_no || item.outbound_no || '';
        if (!String(batchField).toLowerCase().includes(filters.batch_no.toLowerCase())) {
          return false;
        }
      }
      // 备注过滤
      if (filters.remarks && !String(item.remarks || '').toLowerCase().includes(filters.remarks.toLowerCase())) {
        return false;
      }
      return true;
    });
  }

  // 计算当前显示的数据（所有详情页都使用 materials）
  $: rawDisplayData = categoryId ? materials : (viewType === 'remaining' ? materials : []);
  $: filteredDisplayData = filterData(rawDisplayData, activeFilters);
  $: sortedDisplayData = sortData(filteredDisplayData, sortKey, sortDirection);
  $: displayData = sortedDisplayData;
  $: totalItems = displayData.length;
  $: totalPages = Math.ceil(totalItems / pageSize);
  $: paginatedData = displayData.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  $: startIndex = (currentPage - 1) * pageSize + 1;
  $: endIndex = Math.min(currentPage * pageSize, totalItems);

  // 切换视图时重置分页、排序和搜索条件
  $: if (viewType || categoryId) {
    currentPage = 1;
    sortKey = null;
    sortDirection = 'asc';
    resetSearchFilters();
  }

  // Table columns based on view type
  $: columns = getColumns(viewType, !!categoryId);

  $: {
    // When route params change, close form and reset
    const prevProjectId = projectId;
    const prevViewType = viewType;
    const prevCategoryId = categoryId;
    
    projectId = params.projectId;
    viewType = params.viewType;
    categoryId = params.categoryId || null;
    
    // Close form when switching views or categories
    if (prevProjectId !== projectId || prevViewType !== viewType || prevCategoryId !== categoryId) {
      if (showAddForm) {
        showAddForm = false;
        resetForm();
      }
    }
    
    // 更新 projectStore 的选中状态，让 Sidebar 同步高亮
    if (projectId && viewType) {
      projectStore.selectView(projectId, viewType, categoryId);
    }
    
    loadData();
  }

  authStore.subscribe(state => {
    role = state.role;
  });

  // 使用 store 保存项目列表
  let allProjects = [];
  projectStore.subscribe(state => {
    allProjects = state.projects;
  });

  // 响应式更新 project 和 category
  $: {
    if (projectId && allProjects.length > 0) {
      project = allProjects.find(p => p.$id === projectId) || null;
      if (project && categoryId) {
        category = project.categories?.find(c => c.$id === categoryId) || null;
      } else {
        category = null;
      }
    } else {
      project = null;
      category = null;
    }
  }

  function getColumns(type, isDetailPage = false) {
    const baseColumns = [
      { key: 'name', label: '名称', sortable: true, filterable: true },
      { key: 'specification', label: '规格型号', sortable: true, filterable: true },
      { key: 'material_type', label: '材质', sortable: true, filterable: true },
      { key: 'description', label: '材料描述', sortable: false, filterable: true },
      { key: 'unit', label: '单位', sortable: true, filterable: true }
    ];

    if (type === 'inbound') {
      if (isDetailPage) {
        // 详情页：显示每条入库记录的完整信息
        return [
          ...baseColumns,
          { key: 'quantity', label: '入库数量', sortable: true, type: 'number' },
          { key: 'arrival_date', label: '入库时间', sortable: true, type: 'date' },
          { key: 'batch_no', label: '入库单编号', sortable: false },
          { key: 'remarks', label: '备注', sortable: false }
        ];
      } else {
        // 汇总页：只显示入库总量
        return [
          ...baseColumns,
          { key: 'total_inbound', label: '入库总量', sortable: true, type: 'number' }
        ];
      }
    } else if (type === 'outbound') {
      if (isDetailPage) {
        // 详情页：显示每条出库记录的完整信息
        return [
          ...baseColumns,
          { key: 'quantity', label: '出库数量', sortable: true, type: 'number' },
          { key: 'outbound_date', label: '出库时间', sortable: true, type: 'date' },
          { key: 'outbound_no', label: '出库单编号', sortable: false },
          { key: 'remarks', label: '备注', sortable: false }
        ];
      } else {
        // 汇总页：只显示出库总量
        return [
          ...baseColumns,
          { key: 'total_outbound', label: '出库总量', sortable: true, type: 'number' }
        ];
      }
    } else {
      // remaining
      return [
        ...baseColumns,
        { key: 'total_inbound', label: '入库总量', sortable: true, type: 'number' },
        { key: 'total_outbound', label: '出库总量', sortable: true, type: 'number' },
        { key: 'remaining_qty', label: '剩余数量', sortable: true, type: 'number', highlight: true }
      ];
    }
  }

  async function loadData() {
    if (!projectId || !viewType) return;
    
    isLoading = true;
    materials = [];
    records = [];
    categorySummary = [];

    try {
      if (viewType === 'remaining') {
        // For remaining view, show aggregated materials
        const result = categoryId 
          ? await materialsApi.listByCategory(categoryId)
          : await materialsApi.listByProject(projectId);
        
        materials = result.data || [];
      } else if (viewType === 'inbound') {
        // For inbound, show records or summary
        if (categoryId) {
          // 详情页：获取该分类下的入库记录（包含材料信息）
          const result = await inboundRecordsApi.listByCategory(categoryId);
          materials = result.data || [];
        } else {
          // 汇总页：加载分类汇总
          const summaryResult = await categoriesApi.getCategorySummary(projectId, 'inbound');
          categorySummary = summaryResult.data || [];
        }
      } else if (viewType === 'outbound') {
        // For outbound, show records or summary
        if (categoryId) {
          // 详情页：获取该分类下的出库记录（包含材料信息）
          const result = await outboundRecordsApi.listByCategory(categoryId);
          materials = result.data || [];
        } else {
          // 汇总页：加载分类汇总
          const summaryResult = await categoriesApi.getCategorySummary(projectId, 'outbound');
          categorySummary = summaryResult.data || [];
        }
      }
    } catch (error) {
      console.error('Load data error:', error);
      uiStore.showNotification('加载数据失败', 'error');
    } finally {
      isLoading = false;
    }
  }

  function getViewTypeLabel(type) {
    const labels = {
      inbound: '入库材料汇总',
      outbound: '出库材料汇总',
      remaining: '剩余材料汇总'
    };
    return labels[type] || type;
  }

  // Summary table pagination helpers
  function getSummaryCurrentPage(categoryId) {
    return summaryPageMap[categoryId] || 1;
  }

  function setSummaryPage(categoryId, page) {
    summaryPageMap[categoryId] = page;
    summaryPageMap = { ...summaryPageMap };  // 创建新对象触发响应式
    summaryVersion++;  // 增加版本号强制重渲染
  }

  function getSummaryTotalPages(materials) {
    return Math.ceil(materials.length / pageSize);
  }

  function getSummaryPaginatedData(materials, categoryId) {
    const page = getSummaryCurrentPage(categoryId);
    const start = (page - 1) * pageSize;
    return materials.slice(start, start + pageSize);
  }

  // 详情页表头排序处理
  function handleSort(key) {
    if (!sortableFields.includes(key)) return;
    if (sortKey === key) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortKey = key;
      sortDirection = 'asc';
    }
    currentPage = 1;  // 排序后回到第一页
  }

  // 汇总表排序处理
  function getSummarySortState(categoryId) {
    return summarySortMap[categoryId] || { key: null, direction: 'asc' };
  }

  function handleSummarySort(categoryId, key) {
    if (!sortableFields.includes(key)) return;
    const current = getSummarySortState(categoryId);
    if (current.key === key) {
      summarySortMap[categoryId] = { key, direction: current.direction === 'asc' ? 'desc' : 'asc' };
    } else {
      summarySortMap[categoryId] = { key, direction: 'asc' };
    }
    summarySortMap = { ...summarySortMap };  // 创建新对象触发响应式
    // 排序后回到第一页
    summaryPageMap[categoryId] = 1;
    summaryPageMap = { ...summaryPageMap };
    // 增加版本号强制重渲染
    summaryVersion++;
  }

  function getSummarySortedData(materials, categoryId) {
    const sortState = getSummarySortState(categoryId);
    return sortData(materials, sortState.key, sortState.direction);
  }

  function toggleAddForm() {
    showAddForm = !showAddForm;
    if (showAddForm) {
      resetForm();
    }
  }

  function resetForm() {
    formData = {
      name: '',
      specification: '',
      material_type: '',
      description: '',
      unit: '',
      quantity: 0,
      date: new Date().toISOString().split('T')[0],
      batch_no: '',
      remarks: ''
    };
  }

  async function handleSubmit() {
    // === 基础字段验证 ===
    if (!formData.name || !formData.name.trim()) {
      uiStore.showNotification('请输入材料名称', 'error');
      return;
    }

    if (!formData.specification || !formData.specification.trim()) {
      uiStore.showNotification('请输入规格型号', 'error');
      return;
    }

    if (!formData.material_type || !formData.material_type.trim()) {
      uiStore.showNotification('请输入材质', 'error');
      return;
    }

    // === 数量验证 ===
    const qty = parseFloat(formData.quantity);
    
    if (isNaN(qty)) {
      uiStore.showNotification('请输入有效的数量', 'error');
      return;
    }

    if (qty <= 0) {
      uiStore.showNotification('数量必须大于0', 'error');
      return;
    }

    if (qty > 999999) {
      uiStore.showNotification('数量不能超过999999', 'error');
      return;
    }

    // === 日期验证 ===
    if (!formData.date) {
      uiStore.showNotification('请选择日期', 'error');
      return;
    }

    uiStore.showLoading(viewType === 'inbound' ? '入库中...' : '出库中...');
    try {
      // 查找或创建材料
      // 注意：description 已移至 inbound_records/outbound_records
      const materialResult = await materialsApi.findOrCreate(projectId, categoryId, {
        name: formData.name.trim(),
        specification: formData.specification.trim(),
        material_type: formData.material_type.trim(),
        unit: formData.unit?.trim() || ''
      });

      if (materialResult.error) {
        throw materialResult.error;
      }

      const materialId = materialResult.data.$id;

      // 创建记录
      if (viewType === 'inbound') {
        // === 入库记录 ===
        const result = await inboundRecordsApi.create(projectId, categoryId, materialId, {
          quantity: qty,
          arrival_date: formData.date,
          batch_no: formData.batch_no?.trim() || '',
          description: formData.description?.trim() || '',
          remarks: formData.remarks?.trim() || ''
        });

        if (result.error) {
          throw result.error;
        }
        
        uiStore.showNotification(
          `入库成功！材料：${formData.name}，数量：${qty}${formData.unit || ''}`, 
          'success'
        );
      } else if (viewType === 'outbound') {
        // === 出库记录 ===
        const result = await outboundRecordsApi.create(projectId, categoryId, materialId, {
          quantity: qty,
          outbound_date: formData.date,
          outbound_no: formData.batch_no?.trim() || '',
          description: formData.description?.trim() || '',
          remarks: formData.remarks?.trim() || ''
        });

        if (result.error) {
          // 出库失败（库存不足等）
          throw result.error;
        }
        
        uiStore.showNotification(
          `出库成功！材料：${formData.name}，数量：${qty}${formData.unit || ''}`, 
          'success'
        );
      }

      // 成功后清理
      showAddForm = false;
      resetForm();
      await loadData();
      
    } catch (error) {
      console.error('Submit error:', error);
      
      // 详细的错误处理
      let errorMessage = '操作失败';
      
      if (error instanceof Error) {
        errorMessage = error.message;
      } else if (typeof error === 'string') {
        errorMessage = error;
      } else if (error?.message) {
        errorMessage = error.message;
      } else if (error?.toString) {
        errorMessage = error.toString();
      }
      
      // 显示错误，保持表单打开以便修改
      uiStore.showNotification(errorMessage, 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // Excel Import
  let fileInput;

  function handleImportClick() {
    fileInput.click();
  }

  async function handleFileUpload(event) {
    const file = event.target.files[0];
    if (!file) return;

    // 确保 categoryId 存在
    if (!categoryId) {
      uiStore.showNotification('请先选择一个分类再导入', 'error');
      event.target.value = '';
      return;
    }

    console.log('Import starting with categoryId:', categoryId, 'projectId:', projectId);

    uiStore.showLoading('解析Excel文件中...');
    try {
      const data = await file.arrayBuffer();
      const workbook = XLSX.read(data);
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];
      const jsonData = XLSX.utils.sheet_to_json(worksheet);

      if (jsonData.length === 0) {
        uiStore.showNotification('Excel文件为空', 'warning');
        uiStore.hideLoading();
        return;
      }

      // 辅助函数：从多个可能的列名中获取值
      const getField = (row, ...keys) => {
        for (const key of keys) {
          if (row[key] !== undefined && row[key] !== null && row[key] !== '') {
            return row[key];
          }
        }
        return null;
      };

      // 辅助函数：验证 YYYY-MM-DD 格式
      const isValidDateFormat = (str) => {
        if (!str || typeof str !== 'string') return false;
        const regex = /^\d{4}-\d{2}-\d{2}$/;
        if (!regex.test(str)) return false;
        const [year, month, day] = str.split('-').map(Number);
        const date = new Date(year, month - 1, day);
        return date.getFullYear() === year && 
               date.getMonth() === month - 1 && 
               date.getDate() === day;
      };

      // 辅助函数：尝试解析各种日期格式
      const parseDate = (input) => {
        if (input === null || input === undefined || input === '') {
          return { valid: false, reason: '日期为空' };
        }
        
        // 如果是数字，可能是 Excel 序列号
        if (typeof input === 'number' || (typeof input === 'string' && /^\d+$/.test(input.trim()))) {
          const serialNum = typeof input === 'number' ? input : parseInt(input.trim(), 10);
          
          // Excel 序列号范围检查（1900年 到 2100年左右，大约 1 到 73050）
          if (serialNum >= 1 && serialNum <= 100000) {
            // Excel 日期转换：Excel 以 1900-01-01 为第1天（但有个bug，认为1900年是闰年）
            // JavaScript Date 以 1970-01-01 为基准
            // Excel 序列号 1 = 1900-01-01
            // 需要注意 Excel 的 bug：序列号 60 = 1900-02-29（实际不存在）
            const excelEpoch = new Date(Date.UTC(1899, 11, 30)); // 1899-12-30 作为基准
            const jsDate = new Date(excelEpoch.getTime() + serialNum * 24 * 60 * 60 * 1000);
            
            const year = jsDate.getUTCFullYear();
            const month = String(jsDate.getUTCMonth() + 1).padStart(2, '0');
            const day = String(jsDate.getUTCDate()).padStart(2, '0');
            const formatted = `${year}-${month}-${day}`;
            
            // 验证转换后的日期是否合理（1900-2100年）
            if (year >= 1900 && year <= 2100) {
              return { valid: true, date: formatted };
            }
          }
        }
        
        const str = String(input).trim();
        if (!str) return { valid: false, reason: '日期为空' };
        
        // YYYY-MM-DD 格式
        if (isValidDateFormat(str)) return { valid: true, date: str };
        
        // YYYYMMDD 紧凑格式
        const compactMatch = str.match(/^(\d{4})(\d{2})(\d{2})$/);
        if (compactMatch) {
          const [, year, month, day] = compactMatch;
          const formatted = `${year}-${month}-${day}`;
          if (isValidDateFormat(formatted)) return { valid: true, date: formatted };
          return { valid: false, reason: `日期无效: ${formatted}` };
        }
        
        // YYYY/MM/DD 格式
        const slashMatch = str.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})$/);
        if (slashMatch) {
          const [, year, month, day] = slashMatch;
          const formatted = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
          if (isValidDateFormat(formatted)) return { valid: true, date: formatted };
        }
        
        // YYYY年MM月DD日 格式
        const cnMatch = str.match(/^(\d{4})年(\d{1,2})月(\d{1,2})日?$/);
        if (cnMatch) {
          const [, year, month, day] = cnMatch;
          const formatted = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
          if (isValidDateFormat(formatted)) return { valid: true, date: formatted };
        }
        
        // DD/MM/YYYY 格式
        const dmyMatch = str.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
        if (dmyMatch) {
          const [, d, m, y] = dmyMatch;
          const formatted = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
          if (isValidDateFormat(formatted)) return { valid: true, date: formatted };
        }
        
        return { valid: false, reason: `无法解析日期: "${str}"，请使用 YYYY-MM-DD 格式` };
      };

      // ========================================
      // 阶段1：验证所有数据
      // ========================================
      uiStore.showLoading('验证数据中...');
      
      const errorDetails = {
        missingFields: 0,
        duplicateRecords: 0,
        insufficientStock: 0,
        invalidDate: 0,
        invalidQuantity: 0
      };
      const errorList = [];
      const validatedRows = []; // 存储验证通过的行数据

      // 预先获取已有记录，用于唯一性检查
      let existingRecordsData = [];
      if (viewType === 'inbound') {
        const existingResult = await inboundRecordsApi.listByCategory(categoryId);
        existingRecordsData = existingResult.data || [];
      } else if (viewType === 'outbound') {
        const existingResult = await outboundRecordsApi.listByCategory(categoryId);
        existingRecordsData = existingResult.data || [];
      }

      // 预先获取该分类下所有材料（用于出库库存检查）
      let existingMaterials = [];
      if (viewType === 'outbound') {
        const materialsResult = await materialsApi.listByCategory(categoryId);
        existingMaterials = materialsResult.data || [];
      }

      // 用于追踪本次导入中的记录（防止同一批次内重复）
      const importedKeys = new Set();
      // 用于追踪本次导入中的出库数量（累计检查库存）
      const pendingOutbound = new Map();

      for (let rowIndex = 0; rowIndex < jsonData.length; rowIndex++) {
        const row = jsonData[rowIndex];
        const excelRow = rowIndex + 2; // Excel行号（+1表头，+1从0开始）

        // 获取材料信息
        const name = getField(row, '名称', 'name', '材料名称', '物料名称');
        const specification = getField(row, '规格型号', 'specification', '规格', '型号');
        const materialType = getField(row, '材质', 'material_type', '材料类型', '类型');
        
        // 必填字段验证
        if (!name || !specification || !materialType) {
          const missing = [];
          if (!name) missing.push('名称');
          if (!specification) missing.push('规格型号');
          if (!materialType) missing.push('材质');
          errorList.push({ row: excelRow, error: `必填字段缺失: ${missing.join('、')}` });
          errorDetails.missingFields++;
          continue;
        }

        // 数量验证
        const qty = parseFloat(getField(row, '数量', 'quantity', '入库数量', '出库数量') || 0);
        if (isNaN(qty) || qty <= 0) {
          errorList.push({ row: excelRow, error: '数量为空或无效' });
          errorDetails.invalidQuantity++;
          continue;
        }

        // 日期验证
        const dateStr = viewType === 'inbound' 
          ? getField(row, '到货时间', '入库时间', '到货日期', '入库日期', 'arrival_date', 'date', '日期', '时间')
          : getField(row, '出库时间', '出库日期', 'outbound_date', 'date', '日期', '时间');
        
        const parseResult = parseDate(dateStr);
        if (!parseResult.valid) {
          errorList.push({ row: excelRow, error: parseResult.reason });
          errorDetails.invalidDate++;
          continue;
        }
        const formattedDate = parseResult.date;

        // 重复检查
        const uniqueKey = `${String(name).trim()}|${String(specification).trim()}|${String(materialType).trim()}|${formattedDate}`;
        const dateField = viewType === 'inbound' ? 'arrival_date' : 'outbound_date';
        
        const isDuplicateInDb = existingRecordsData.some(record => 
          record.name === String(name).trim() &&
          record.specification === String(specification).trim() &&
          record.material_type === String(materialType).trim() &&
          record[dateField]?.substring(0, 10) === formattedDate
        );
        
        const isDuplicateInImport = importedKeys.has(uniqueKey);
        
        if (isDuplicateInDb || isDuplicateInImport) {
          errorList.push({ row: excelRow, error: '数据重复（名称+规格+材质+日期已存在）' });
          errorDetails.duplicateRecords++;
          continue;
        }

        // 出库时检查库存（包括本次导入的累计）
        if (viewType === 'outbound') {
          const materialKey = `${String(name).trim()}|${String(specification).trim()}|${String(materialType).trim()}`;
          const existingMat = existingMaterials.find(m => 
            m.name === String(name).trim() &&
            m.specification === String(specification).trim() &&
            m.material_type === String(materialType).trim()
          );
          
          const currentRemaining = existingMat?.remaining_qty || 0;
          const alreadyPending = pendingOutbound.get(materialKey) || 0;
          const availableQty = currentRemaining - alreadyPending;
          
          if (qty > availableQty) {
            errorList.push({ row: excelRow, error: `库存不足（需${qty}，可用${availableQty}）` });
            errorDetails.insufficientStock++;
            continue;
          }
          
          // 累计本行的出库数量
          pendingOutbound.set(materialKey, alreadyPending + qty);
        }

        // 验证通过，记录该行
        importedKeys.add(uniqueKey);
        validatedRows.push({
          row,
          rowIndex,
          excelRow,
          name: String(name).trim(),
          specification: String(specification).trim(),
          materialType: String(materialType).trim(),
          qty,
          formattedDate,
          description: String(getField(row, '材料描述', 'description', '描述') || '').trim(),
          unit: String(getField(row, '单位', 'unit') || '').trim(),
          batch_no: viewType === 'inbound' 
            ? String(getField(row, '到货单编号', '入库单编号', 'batch_no', '单据编号', '编号') || '').trim()
            : String(getField(row, '出库单编号', 'outbound_no', '单据编号', '编号') || '').trim(),
          remarks: String(getField(row, '备注', 'remarks', '说明') || '').trim()
        });
      }

      // ========================================
      // 检查验证结果
      // ========================================
      if (errorList.length > 0) {
        // 有错误，不执行导入
        console.warn('=== 导入验证失败 ===');
        errorList.forEach(e => console.warn(`第${e.row}行: ${e.error}`));
        console.warn('====================');
        
        // 构建错误信息
        const errorMessages = [];
        if (errorDetails.missingFields > 0) errorMessages.push(`字段缺失 ${errorDetails.missingFields}`);
        if (errorDetails.invalidQuantity > 0) errorMessages.push(`数量无效 ${errorDetails.invalidQuantity}`);
        if (errorDetails.invalidDate > 0) errorMessages.push(`日期有误 ${errorDetails.invalidDate}`);
        if (errorDetails.duplicateRecords > 0) errorMessages.push(`重复 ${errorDetails.duplicateRecords}`);
        if (errorDetails.insufficientStock > 0) errorMessages.push(`库存不足 ${errorDetails.insufficientStock}`);
        
        // 显示错误详情（最多10条）
        const maxShow = 10;
        const errorLines = errorList.slice(0, maxShow).map(e => `第${e.row}行: ${e.error}`);
        if (errorList.length > maxShow) {
          errorLines.push(`...还有 ${errorList.length - maxShow} 条错误`);
        }
        
        const summary = `验证失败: ${errorList.length} 条数据有问题 (${errorMessages.join('、')})`;
        const fullMessage = [summary, '', '请修正后重新导入：', ...errorLines].join('\n');
        uiStore.showNotification(fullMessage, 'error', 15000);
        uiStore.hideLoading();
        event.target.value = '';
        return;
      }

      // ========================================
      // 阶段2：执行导入（所有数据已验证通过）
      // ========================================
      uiStore.showLoading(`正在导入 ${validatedRows.length} 条数据...`);
      
      let successCount = 0;
      let importErrors = [];
      const batchSize = 10;

      for (let i = 0; i < validatedRows.length; i += batchSize) {
        const batch = validatedRows.slice(i, Math.min(i + batchSize, validatedRows.length));
        uiStore.showLoading(`导入中... ${Math.min(i + batchSize, validatedRows.length)}/${validatedRows.length}`);

        for (const item of batch) {
          try {
            // 查找或创建材料
            const materialResult = await materialsApi.findOrCreate(projectId, categoryId, {
              name: item.name,
              specification: item.specification,
              material_type: item.materialType,
              unit: item.unit
            });

            if (materialResult.error) throw materialResult.error;
            if (!materialResult.data) throw new Error('材料创建失败');

            // 创建记录
            let createResult;
            if (viewType === 'inbound') {
              createResult = await inboundRecordsApi.create(projectId, categoryId, materialResult.data.$id, {
                quantity: item.qty,
                arrival_date: item.formattedDate,
                batch_no: item.batch_no,
                description: item.description,
                remarks: item.remarks
              });
            } else {
              createResult = await outboundRecordsApi.create(projectId, categoryId, materialResult.data.$id, {
                quantity: item.qty,
                outbound_date: item.formattedDate,
                outbound_no: item.batch_no,
                description: item.description,
                remarks: item.remarks
              });
            }
            
            if (createResult?.error) throw createResult.error;
            if (!createResult?.data) throw new Error('记录创建失败');
            
            successCount++;
          } catch (rowError) {
            console.error(`Import row ${item.excelRow} failed:`, rowError);
            importErrors.push({ row: item.excelRow, error: rowError.message });
          }
        }

        // 小延迟
        if (i + batchSize < validatedRows.length) {
          await new Promise(resolve => setTimeout(resolve, 100));
        }
      }

      // 显示导入结果
      if (importErrors.length === 0) {
        uiStore.showNotification(`成功导入 ${successCount} 条数据`, 'success');
      } else {
        // 部分导入失败（理论上不应该发生，因为已验证通过）
        const errorLines = importErrors.slice(0, 5).map(e => `第${e.row}行: ${e.error}`);
        const msg = `导入完成: 成功 ${successCount} 条，失败 ${importErrors.length} 条\n${errorLines.join('\n')}`;
        uiStore.showNotification(msg, 'warning', 10000);
      }
      
      await loadData();
    } catch (error) {
      console.error('Import error:', error);
      uiStore.showNotification('导入失败: ' + error.message, 'error');
    } finally {
      uiStore.hideLoading();
    }

    // Reset file input
    event.target.value = '';
  }

  // Download Excel Template
  function handleDownloadTemplate() {
    // 获取导入时需要的模板表头
    const templateColumns = getTemplateColumns(viewType);
    
    if (templateColumns.length === 0) {
      uiStore.showNotification('当前视图无法生成模板', 'warning');
      return;
    }

    // 创建示例数据行
    const mockData = getMockRowData(viewType);
    const mockRow = {};
    templateColumns.forEach(col => {
      mockRow[col.label] = mockData[col.key] || '';
    });

    // 创建worksheet，包含示例数据行
    const ws = XLSX.utils.json_to_sheet([mockRow]);
    
    // 设置列宽
    const colWidths = templateColumns.map(col => ({ wch: Math.max(col.label.length * 2, 12) }));
    ws['!cols'] = colWidths;

    // 创建workbook
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '导入模板');

    // 下载
    const typeLabel = viewType === 'inbound' ? '入库' : '出库';
    const fileName = `${typeLabel}材料导入模板.xlsx`;
    XLSX.writeFile(wb, fileName);
    
    uiStore.showNotification('模板下载成功', 'success');
  }

  // 获取模板需要的列
  function getTemplateColumns(type) {
    const baseColumns = [
      { key: 'name', label: '名称' },
      { key: 'specification', label: '规格型号' },
      { key: 'material_type', label: '材质' },
      { key: 'description', label: '材料描述' },
      { key: 'unit', label: '单位' }
    ];

    if (type === 'inbound') {
      return [
        ...baseColumns,
        { key: 'quantity', label: '入库数量' },
        { key: 'arrival_date', label: '入库时间' },
        { key: 'batch_no', label: '入库单编号' },
        { key: 'remarks', label: '备注' }
      ];
    } else if (type === 'outbound') {
      return [
        ...baseColumns,
        { key: 'quantity', label: '出库数量' },
        { key: 'outbound_date', label: '出库时间' },
        { key: 'outbound_no', label: '出库单编号' },
        { key: 'remarks', label: '备注' }
      ];
    }
    return [];
  }

  // 获取模板示例数据
  function getMockRowData(type) {
    const today = new Date().toISOString().split('T')[0];
    const baseData = {
      name: '示例材料名称',
      specification: 'DN100 SCH40',
      material_type: 'SS304',
      description: '这是材料描述示例',
      unit: '个'
    };

    if (type === 'inbound') {
      return {
        ...baseData,
        quantity: 100,
        arrival_date: today,
        batch_no: 'DH-2024-001',
        remarks: '备注示例'
      };
    } else if (type === 'outbound') {
      return {
        ...baseData,
        quantity: 50,
        outbound_date: today,
        outbound_no: 'CK-2024-001',
        remarks: '备注示例'
      };
    }
    return baseData;
  }

  // Excel Export
  function handleExport() {
    const dataToExport = viewType === 'remaining' ? materials : records;
    
    if (dataToExport.length === 0) {
      uiStore.showNotification('没有数据可导出', 'warning');
      return;
    }

    // Create worksheet
    const ws = XLSX.utils.json_to_sheet(dataToExport.map(item => {
      const row = {};
      columns.forEach(col => {
        row[col.label] = item[col.key] || '';
      });
      return row;
    }));

    // Create workbook
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, getViewTypeLabel(viewType));

    // Download
    const fileName = `${project?.name || 'export'}_${getViewTypeLabel(viewType)}_${new Date().toISOString().split('T')[0]}.xlsx`;
    XLSX.writeFile(wb, fileName);
  }

  // Create Category
  let showCreateCategory = false;
  let newCategoryName = '';

  async function handleCreateCategory() {
    if (!newCategoryName.trim()) {
      uiStore.showNotification('请输入分类名称', 'error');
      return;
    }

    uiStore.showLoading('创建分类中...');
    try {
      const result = await categoriesApi.create(projectId, newCategoryName);
      if (result.error) throw result.error;

      uiStore.showNotification('分类创建成功', 'success');
      showCreateCategory = false;
      newCategoryName = '';
      
      // Reload projects to update sidebar
      window.location.reload();
    } catch (error) {
      console.error('Create category error:', error);
      // 显示具体错误信息
      const errorMsg = error?.message || '创建失败';
      uiStore.showNotification(errorMsg, 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // =============================================
  // Rename Category Functions
  // =============================================
  function openRenameModal(item) {
    renamingCategory = item;
    newCategoryNameInput = item.categoryName;
    showRenameModal = true;
  }

  function closeRenameModal() {
    showRenameModal = false;
    renamingCategory = null;
    newCategoryNameInput = '';
  }

  async function handleRenameCategory() {
    if (!newCategoryNameInput.trim()) {
      uiStore.showNotification('请输入分类名称', 'error');
      return;
    }

    if (newCategoryNameInput.trim() === renamingCategory.categoryName) {
      uiStore.showNotification('名称未修改', 'warning');
      return;
    }

    uiStore.showLoading('重命名中...');
    try {
      const result = await categoriesApi.update(renamingCategory.categoryId, {
        name: newCategoryNameInput.trim()
      });
      
      if (result.error) throw result.error;

      uiStore.showNotification('重命名成功', 'success');
      closeRenameModal();
      
      // Reload to update both summary and sidebar
      window.location.reload();
    } catch (error) {
      console.error('Rename category error:', error);
      const errorMsg = error?.message || '重命名失败';
      uiStore.showNotification(errorMsg, 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // =============================================
  // Edit & Delete Record Functions
  // =============================================
  
  // 检查当前用户是否可以编辑记录
  function canEditCurrentRecord() {
    if (viewType === 'inbound') {
      return canEditInbound(role);
    } else if (viewType === 'outbound') {
      return canEditOutbound(role);
    }
    return false;
  }

  // 打开编辑模态框
  function openEditModal(record) {
    editingRecord = record;
    if (viewType === 'inbound') {
      editFormData = {
        description: record.description || '',
        unit: record.unit || '',
        quantity: record.quantity,
        date: record.arrival_date || '',
        batch_no: record.batch_no || '',
        remarks: record.remarks || ''
      };
    } else if (viewType === 'outbound') {
      editFormData = {
        description: record.description || '',
        unit: record.unit || '',
        quantity: record.quantity,
        date: record.outbound_date || '',
        batch_no: record.outbound_no || '',
        remarks: record.remarks || ''
      };
    }
    showEditModal = true;
  }

  // 关闭编辑模态框
  function closeEditModal() {
    showEditModal = false;
    editingRecord = null;
    editFormData = {
      description: '',
      unit: '',
      quantity: 0,
      date: '',
      batch_no: '',
      remarks: ''
    };
  }

  // 保存编辑
  async function handleSaveEdit() {
    if (!editingRecord) return;

    const qty = parseFloat(editFormData.quantity);
    if (isNaN(qty) || qty <= 0) {
      uiStore.showNotification('请输入有效的数量', 'error');
      return;
    }

    uiStore.showLoading('保存中...');
    try {
      let result;
      
      // 更新材料的 unit（description 已移至 record）
      if (editFormData.unit !== editingRecord.unit) {
        await materialsApi.updateInfo(editingRecord.material_id, {
          unit: editFormData.unit
        });
      }
      
      if (viewType === 'inbound') {
        result = await inboundRecordsApi.update(editingRecord.$id, editingRecord.material_id, {
          quantity: qty,
          arrival_date: editFormData.date,
          batch_no: editFormData.batch_no,
          description: editFormData.description,
          remarks: editFormData.remarks
        });
      } else if (viewType === 'outbound') {
        result = await outboundRecordsApi.update(editingRecord.$id, editingRecord.material_id, {
          quantity: qty,
          outbound_date: editFormData.date,
          outbound_no: editFormData.batch_no,
          description: editFormData.description,
          remarks: editFormData.remarks
        });
      }

      if (result?.error) {
        throw result.error;
      }

      uiStore.showNotification('修改成功', 'success');
      closeEditModal();
      await loadData();
    } catch (error) {
      console.error('Update error:', error);
      uiStore.showNotification('修改失败: ' + (error.message || '未知错误'), 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // 删除记录
  async function handleDeleteRecord(record) {
    const confirmMsg = viewType === 'inbound' 
      ? `确定删除这条入库记录吗？\n材料: ${record.name}\n数量: ${record.quantity}`
      : `确定删除这条出库记录吗？\n材料: ${record.name}\n数量: ${record.quantity}`;
    
    if (!confirm(confirmMsg)) return;

    uiStore.showLoading('删除中...');
    try {
      let result;
      if (viewType === 'inbound') {
        result = await inboundRecordsApi.delete(record.$id, record.material_id);
      } else if (viewType === 'outbound') {
        result = await outboundRecordsApi.delete(record.$id, record.material_id);
      }

      if (result?.error) {
        throw result.error;
      }

      uiStore.showNotification('删除成功', 'success');
      await loadData();
    } catch (error) {
      console.error('Delete error:', error);
      uiStore.showNotification('删除失败: ' + (error.message || '未知错误'), 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // =============================================
  // Pagination Functions
  // =============================================
  function goToPage(page) {
    if (page >= 1 && page <= totalPages) {
      currentPage = page;
    }
  }

  function changePageSize(newSize) {
    pageSize = newSize;
    currentPage = 1; // 重置到第一页
  }

  function getVisiblePages() {
    const pages = [];
    const maxVisible = 5;
    
    if (totalPages <= maxVisible) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      // 始终显示第一页
      pages.push(1);
      
      let start = Math.max(2, currentPage - 1);
      let end = Math.min(totalPages - 1, currentPage + 1);
      
      if (currentPage <= 3) {
        end = Math.min(4, totalPages - 1);
      }
      if (currentPage >= totalPages - 2) {
        start = Math.max(2, totalPages - 3);
      }
      
      if (start > 2) pages.push('...');
      
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      
      if (end < totalPages - 1) pages.push('...');
      
      // 始终显示最后一页
      if (totalPages > 1) pages.push(totalPages);
    }
    
    return pages;
  }
</script>

