      </div>
      <div class="search-actions">
        <button class="btn btn-primary btn-sm" on:click={applySearch}>
          🔍 搜索
        </button>
        <button class="btn btn-secondary btn-sm" on:click={resetSearchFilters}>
          ↺ 重置
        </button>
        {#if Object.values(activeFilters).some(v => v)}
          <span class="filter-status">已筛选: {totalItems} 条结果</span>
        {/if}
      </div>
    </div>
  {/if}

  <!-- Toolbar -->
  <div class="toolbar">
    <div class="toolbar-left">
      {#if categoryId && viewType !== 'remaining'}
        {#if (viewType === 'inbound' && canInbound(role)) || (viewType === 'outbound' && canOutbound(role))}
          <button class="btn btn-primary" on:click={toggleAddForm}>
            {showAddForm ? '取消' : '+ 新增记录'}
          </button>
          <button class="btn btn-outline" on:click={handleDownloadTemplate}>
            📋 下载Excel模板
          </button>
          <button class="btn btn-secondary" on:click={handleImportClick}>
            📥 导入Excel
          </button>
          <input 
            type="file" 
            accept=".xlsx,.xls" 
            bind:this={fileInput}
            on:change={handleFileUpload}
            style="display: none;"
          />
        {/if}
      {/if}
      {#if viewType === 'inbound' && !categoryId && canCreateProject(role)}
        <button class="btn btn-primary" on:click={() => showCreateCategory = true}>
          + 新建分类
        </button>
      {/if}
    </div>
    <div class="toolbar-right">
      <button class="btn btn-outline" on:click={handleExport}>
        📤 导出Excel
      </button>
    </div>
  </div>

  <!-- Add Form -->
  {#if showAddForm && categoryId}
    <div class="add-form">
      <h3>{viewType === 'inbound' ? '新增入库记录' : '新增出库记录'}</h3>
      <div class="form-grid">
        <div class="form-group">
          <label>名称 *</label>
          <input 
            type="text" 
            bind:value={formData.name} 
            placeholder="材料名称"
            required
            maxlength="100"
          />
        </div>
        <div class="form-group">
          <label>规格型号 *</label>
          <input 
            type="text" 
            bind:value={formData.specification} 
            placeholder="如: DN400 SCH10"
            required
            maxlength="100"
          />
        </div>
        <div class="form-group">
          <label>材质 *</label>
          <input 
            type="text" 
            bind:value={formData.material_type} 
            placeholder="如: S31803"
            required
            maxlength="50"
          />
        </div>
        <div class="form-group">
          <label>材料描述</label>
          <input 
            type="text" 
            bind:value={formData.description}
            maxlength="500"
          />
        </div>
        <div class="form-group">
          <label>单位</label>
          <input 
            type="text" 
            bind:value={formData.unit} 
            placeholder="如: 米、个"
            maxlength="20"
          />
        </div>
        <div class="form-group">
          <label>数量 *</label>
          <input 
            type="number" 
            bind:value={formData.quantity} 
            min="1" 
            max="999999"
            step="1"
            required
            placeholder="请输入大于0的数量"
          />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '入库时间' : '出库时间'}</label>
          <input type="date" bind:value={formData.date} />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '入库单编号' : '出库单编号'}</label>
          <input type="text" bind:value={formData.batch_no} />
        </div>
        <div class="form-group full-width">
          <label>备注</label>
          <input type="text" bind:value={formData.remarks} />
        </div>
      </div>
      <div class="form-actions">
        <button class="btn btn-primary" on:click={handleSubmit}>保存</button>
        <button class="btn btn-secondary" on:click={toggleAddForm}>取消</button>
      </div>
    </div>
  {/if}

  <!-- Create Category Modal -->
  {#if showCreateCategory}
    <div class="modal-overlay" on:click={() => showCreateCategory = false} on:keydown={(e) => e.key === 'Escape' && (showCreateCategory = false)} role="button" tabindex="-1">
      <div class="modal" on:click|stopPropagation>
        <div class="modal-header">
          <h3>新建材料分类</h3>
          <button class="close-btn" on:click={() => showCreateCategory = false}>×</button>
        </div>
        <div class="modal-body">
          <div class="form-group">
            <label>分类名称</label>
            <input 
              type="text" 
              bind:value={newCategoryName} 
              placeholder="如: 管道、管件、阀门"
            />
          </div>
          <div class="form-actions">
            <button class="btn btn-primary" on:click={handleCreateCategory}>创建</button>
            <button class="btn btn-secondary" on:click={() => showCreateCategory = false}>取消</button>
          </div>
        </div>
      </div>
    </div>
  {/if}

  <!-- Rename Category Modal -->
  {#if showRenameModal}
    <div class="modal-overlay" on:click={closeRenameModal} on:keydown={(e) => e.key === 'Escape' && closeRenameModal()} role="button" tabindex="-1">
      <div class="modal" on:click|stopPropagation>
        <div class="modal-header">
          <h3>重命名分类</h3>
          <button class="close-btn" on:click={closeRenameModal}>×</button>
        </div>
        <div class="modal-body">
          <div class="form-group">
            <label>分类名称</label>
            <input 
              type="text" 
              bind:value={newCategoryNameInput} 
              placeholder="请输入新的分类名称"
            />
          </div>
          <div class="form-actions">
            <button class="btn btn-primary" on:click={handleRenameCategory}>保存</button>
            <button class="btn btn-secondary" on:click={closeRenameModal}>取消</button>
          </div>
        </div>
      </div>
    </div>
  {/if}

  <!-- Data Display -->
  {#if isLoading}
    <div class="loading">
      <div class="spinner"></div>
      <p>加载中...</p>
    </div>
  {:else if !categoryId && viewType !== 'remaining'}
    <!-- Category Summary Table -->
    <div class="category-summary">
      <h3 class="summary-title">
        {viewType === 'inbound' ? '📥 入库汇总' : '📤 出库汇总'}
      </h3>
      {#if categorySummary.length > 0}
        {#each categorySummary as cat, catIndex (cat.categoryId + '-' + summaryVersion)}
          {@const catSortState = summarySortMap[cat.categoryId] || { key: null, direction: 'asc' }}
          {@const catSortedData = sortData(cat.materials, catSortState.key, catSortState.direction)}
          {@const catCurrentPage = summaryPageMap[cat.categoryId] || 1}
          {@const catTotalPages = Math.ceil(catSortedData.length / pageSize)}
          {@const catPaginatedData = catSortedData.slice((catCurrentPage - 1) * pageSize, catCurrentPage * pageSize)}
          {@const catStartIndex = (catCurrentPage - 1) * pageSize}
          <div class="category-section">
            <h4 class="category-header">
              <a 
                href="#/project/{projectId}/{viewType}/{cat.categoryId}" 
                class="category-link"
              >
                {cat.categoryName}
              </a>
              <span class="material-count">({cat.materials.length}种材料)</span>
            </h4>
            {#if cat.materials.length > 0}
              <table class="summary-table">
                <thead>
                  <tr>
                    <th class="row-number-col">#</th>
                    <th 
                      class="sortable" 
                      class:sorted={catSortState.key === 'name'}
                      on:click={() => handleSummarySort(cat.categoryId, 'name')}
                    >
                      名称
                      <span class="sort-indicator">
                        {#if catSortState.key === 'name'}
                          {catSortState.direction === 'asc' ? '↑' : '↓'}
                        {:else}
                          ↕
                        {/if}
                      </span>
                    </th>
                    <th 
                      class="sortable" 
                      class:sorted={catSortState.key === 'specification'}
                      on:click={() => handleSummarySort(cat.categoryId, 'specification')}
                    >
                      规格型号
                      <span class="sort-indicator">
                        {#if catSortState.key === 'specification'}
                          {catSortState.direction === 'asc' ? '↑' : '↓'}
                        {:else}
                          ↕
                        {/if}
                      </span>
                    </th>
                    <th 
                      class="sortable" 
                      class:sorted={catSortState.key === 'material_type'}
                      on:click={() => handleSummarySort(cat.categoryId, 'material_type')}
                    >
                      材质
                      <span class="sort-indicator">
                        {#if catSortState.key === 'material_type'}
                          {catSortState.direction === 'asc' ? '↑' : '↓'}
                        {:else}
                          ↕
                        {/if}
                      </span>
                    </th>
                    <th 
                      class="sortable" 
                      class:sorted={catSortState.key === 'description'}
                      on:click={() => handleSummarySort(cat.categoryId, 'description')}
                    >
                      材料描述
                      <span class="sort-indicator">
                        {#if catSortState.key === 'description'}
                          {catSortState.direction === 'asc' ? '↑' : '↓'}
                        {:else}
                          ↕
                        {/if}
                      </span>
                    </th>
                    <th>单位</th>
                    <th class="quantity-col">{viewType === 'inbound' ? '入库总量' : '出库总量'}</th>
                  </tr>
                </thead>
                <tbody>
                  {#each catPaginatedData as mat, index}
                    <tr>
                      <td class="row-number">{catStartIndex + index + 1}</td>
                      <td>{mat.name}</td>
                      <td>{mat.specification}</td>
                      <td>{mat.material_type}</td>
                      <td>{mat.description || '-'}</td>
                      <td>{mat.unit || '-'}</td>
                      <td class="quantity-value">{mat.quantity}</td>
                    </tr>
                  {/each}
                </tbody>
              </table>
              
              <!-- Pagination for this category -->
              {#if catTotalPages > 1}
                <div class="summary-pagination">
                  <span class="pagination-info">
                    第 {catStartIndex + 1}-{Math.min(catStartIndex + pageSize, cat.materials.length)} 条，共 {cat.materials.length} 条
                  </span>
                  <div class="pagination-controls">
                    <button 
                      class="page-btn" 
                      disabled={catCurrentPage === 1}
                      on:click={() => setSummaryPage(cat.categoryId, catCurrentPage - 1)}
                    >
                      ‹
                    </button>
                    {#each Array(catTotalPages) as _, i}
                      {#if catTotalPages <= 7 || i === 0 || i === catTotalPages - 1 || Math.abs(i - (catCurrentPage - 1)) <= 1}
                        <button 
                          class="page-btn" 
                          class:active={catCurrentPage === i + 1}
                          on:click={() => setSummaryPage(cat.categoryId, i + 1)}
                        >
                          {i + 1}
                        </button>
                      {:else if Math.abs(i - (catCurrentPage - 1)) === 2}
                        <span class="page-ellipsis">...</span>
                      {/if}
                    {/each}
                    <button 
                      class="page-btn" 
                      disabled={catCurrentPage === catTotalPages}
                      on:click={() => setSummaryPage(cat.categoryId, catCurrentPage + 1)}
                    >
                      ›
                    </button>
                  </div>
                </div>
              {/if}
            {:else}
              <p class="no-materials">暂无材料数据</p>
            {/if}
          </div>
        {/each}
      {:else}
        <div class="empty-summary">
          <p>暂无分类数据</p>
        </div>
      {/if}
      
      <div class="summary-tip">
        <p>💡 点击分类名称查看详细记录</p>
        {#if viewType === 'inbound' && canCreateProject(role)}
          <button class="btn btn-primary" on:click={() => showCreateCategory = true}>
            + 新建分类
          </button>
        {/if}
      </div>
    </div>
  {:else}
    <!-- Data Table with Actions -->
    <div class="data-table-container">
      <table class="data-table">
        <thead>
          <tr>
            <th class="row-number-col">#</th>
            {#each columns as col}
              <th 
                class:sortable={sortableFields.includes(col.key)}
                class:sorted={sortKey === col.key}
                on:click={() => handleSort(col.key)}
              >
                {col.label}
                {#if sortableFields.includes(col.key)}
                  <span class="sort-indicator">
                    {#if sortKey === col.key}
                      {sortDirection === 'asc' ? '↑' : '↓'}
                    {:else}
                      ↕
                    {/if}
                  </span>
                {/if}
              </th>
            {/each}
            {#if viewType !== 'remaining' && canEditCurrentRecord()}
              <th class="actions-col">操作</th>
            {/if}
          </tr>
        </thead>
        <tbody>
          {#each paginatedData as row, index}
            <tr>
              <td class="row-number">{startIndex + index}</td>
              {#each columns as col}
                <td 
                  class:highlight={col.highlight}
                  class:negative={col.key === 'remaining_qty' && (row[col.key] ?? 0) < 0}
                >
                  {#if col.type === 'number'}
                    {row[col.key] ?? 0}
                  {:else if col.type === 'date'}
                    {row[col.key] ? String(row[col.key]).substring(0, 10) : '-'}
                  {:else}
                    {row[col.key] || '-'}
                  {/if}
                </td>
              {/each}
              {#if viewType !== 'remaining' && canEditCurrentRecord()}
                <td class="actions-cell">
                  <button 
                    class="btn-icon btn-edit" 
                    on:click={() => openEditModal(row)}
                    title="编辑"
                  >
                    ✏️
                  </button>
                  <button 
                    class="btn-icon btn-delete" 
                    on:click={() => handleDeleteRecord(row)}
                    title="删除"
                  >
                    🗑️
                  </button>
                </td>
              {/if}
            </tr>
          {:else}
            <tr>
              <td colspan={columns.length + (viewType !== 'remaining' && canEditCurrentRecord() ? 2 : 1)} class="empty-row">
                暂无数据
              </td>
            </tr>
          {/each}
        </tbody>
      </table>
    </div>

    <!-- Pagination -->
    {#if totalItems > 0}
      <div class="pagination">
        <div class="pagination-info">
          <span>共 {totalItems} 条，显示 {startIndex}-{endIndex} 条</span>
          <span class="page-size-select">
            每页
            <select bind:value={pageSize} on:change={() => changePageSize(pageSize)}>
              {#each pageSizeOptions as size}
                <option value={size}>{size}</option>
              {/each}
            </select>
            条
          </span>
        </div>
        
        <div class="pagination-controls">
          <button 
            class="page-btn" 
            disabled={currentPage === 1}
            on:click={() => goToPage(1)}
            title="首页"
          >
            «
          </button>
          <button 
            class="page-btn" 
            disabled={currentPage === 1}
            on:click={() => goToPage(currentPage - 1)}
            title="上一页"
          >
            ‹
          </button>
          
          {#each getVisiblePages() as page}
            {#if page === '...'}
              <span class="page-ellipsis">...</span>
            {:else}
              <button 
                class="page-btn" 
                class:active={currentPage === page}
                on:click={() => goToPage(page)}
              >
                {page}
              </button>
            {/if}
          {/each}
          
          <button 
            class="page-btn" 
            disabled={currentPage === totalPages}
            on:click={() => goToPage(currentPage + 1)}
            title="下一页"
          >
            ›
          </button>
          <button 
            class="page-btn" 
            disabled={currentPage === totalPages}
            on:click={() => goToPage(totalPages)}
            title="末页"
          >
            »
          </button>
        </div>
      </div>
    {/if}
  {/if}
</div>

<!-- Edit Modal -->
{#if showEditModal && editingRecord}
  <div class="modal-overlay" on:click={closeEditModal}>
    <div class="modal" on:click|stopPropagation>
      <div class="modal-header">
        <h3>{viewType === 'inbound' ? '编辑入库记录' : '编辑出库记录'}</h3>
        <button class="btn-close" on:click={closeEditModal}>×</button>
      </div>
      <div class="modal-body">
        <div class="edit-info">
          <p><strong>材料：</strong>{editingRecord.name}</p>
          <p><strong>规格：</strong>{editingRecord.specification}</p>
          <p><strong>材质：</strong>{editingRecord.material_type}</p>
        </div>
        <div class="form-group">
          <label>材料描述</label>
          <input 
            type="text" 
            bind:value={editFormData.description}
            maxlength="500"
          />
        </div>
        <div class="form-group">
          <label>单位</label>
          <input 
            type="text" 
            bind:value={editFormData.unit}
            maxlength="20"
          />
        </div>
        <div class="form-group">
          <label>入库数量 *</label>
          <input 
            type="number" 
            bind:value={editFormData.quantity}
            min="0.01"
            step="0.01"
            required
          />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '入库时间' : '出库时间'} *</label>
          <input 
            type="date" 
            bind:value={editFormData.date}
            required
          />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '入库单编号' : '出库单编号'}</label>
          <input 
            type="text" 
            bind:value={editFormData.batch_no}
            maxlength="100"
          />
        </div>
        <div class="form-group">
          <label>备注</label>
          <textarea 
            bind:value={editFormData.remarks}
            rows="2"
            maxlength="500"
          ></textarea>
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn btn-secondary" on:click={closeEditModal}>取消</button>
        <button class="btn btn-primary" on:click={handleSaveEdit}>保存</button>
      </div>
    </div>
  </div>
{/if}

