
// 安全地获取 process.env（浏览器环境中不存在）
const getProcessEnv = (key) => {
  if (typeof process !== 'undefined' && process.env) {
    return process.env[key];
  }
  return undefined;
};

const getEnv = (key, fallback) => {
  if (typeof window !== 'undefined' && window.__ENV && window.__ENV[key]) {
    return window.__ENV[key];
  }
  return fallback;
};

export const config = {
  // Super Admin (from environment)
  SUPER_ADMIN_USERNAME: getEnv('SUPER_ADMIN_USERNAME', getProcessEnv('SUPER_ADMIN_USERNAME')),
  SUPER_ADMIN_PASSWORD: getEnv('SUPER_ADMIN_PASSWORD', getProcessEnv('SUPER_ADMIN_PASSWORD')),

  PERSISTENCE_PROVIDER: getEnv('PERSISTENCE_PROVIDER', getProcessEnv('PERSISTENCE_PROVIDER')),

  // Supabase
  SUPABASE_URL: getEnv('SUPABASE_URL', getProcessEnv('SUPABASE_URL')),
  SUPABASE_ANON_KEY: getEnv('SUPABASE_ANON_KEY', getProcessEnv('SUPABASE_ANON_KEY')),
  SUPABASE_SERVICE_ROLE_KEY: getEnv('SUPABASE_SERVICE_ROLE_KEY', getProcessEnv('SUPABASE_SERVICE_ROLE_KEY')),

  // Appwrite
  APPWRITE_URL: getEnv('APPWRITE_URL', getProcessEnv('APPWRITE_URL')),
  APPWRITE_PROJECT_ID: getEnv('APPWRITE_PROJECT_ID', getProcessEnv('APPWRITE_PROJECT_ID')),
  APPWRITE_DATABASE_ID: getEnv('APPWRITE_DATABASE_ID', getProcessEnv('APPWRITE_DATABASE_ID')),
  APPWRITE_API_KEY: getEnv('APPWRITE_API_KEY', getProcessEnv('APPWRITE_API_KEY')),
  // 密码修改模式: 'api_key' 或 'function'
  APPWRITE_PASSWORD_MODE: getEnv('APPWRITE_PASSWORD_MODE', getProcessEnv('APPWRITE_PASSWORD_MODE')) || 'api_key',
  // Function 模式下的用户管理函数ID
  APPWRITE_FUNCTION_USER_MANAGEMENT: getEnv('APPWRITE_FUNCTION_USER_MANAGEMENT', getProcessEnv('APPWRITE_FUNCTION_USER_MANAGEMENT')),

  // PocketBase
  POCKETBASE_URL: getEnv('POCKETBASE_URL', getProcessEnv('POCKETBASE_URL'))
};
