// BMMS Database Service
// Provides high-level API for BMMS operations on top of Appwrite

import { db } from '../providers/index.js';

// Collection names (must match Appwrite database schema)
export const COLLECTIONS = {
    PROJECTS: 'projects',
    CATEGORIES: 'categories',
    MATERIALS: 'materials',
    INBOUND_RECORDS: 'inbound_records',
    OUTBOUND_RECORDS: 'outbound_records',
    USERS: 'users'
};

// =============================================
// Projects API
// =============================================
export const projectsApi = {
    async list() {
        const result = await db.from(COLLECTIONS.PROJECTS).select('*').order('created_at', { ascending: false }).exec();
        return result;
    },

    async create(name, description = '', createdBy) {
        const data = {
            name,
            description,
            created_by: createdBy
        };
        return await db.from(COLLECTIONS.PROJECTS).insert(data);
    },

    async update(projectId, data) {
        return await db.from(COLLECTIONS.PROJECTS).update(data).eq('$id', projectId);
    },

    async delete(projectId) {
        // First delete all related categories, materials, and records
        await categoriesApi.deleteByProject(projectId);
        return await db.from(COLLECTIONS.PROJECTS).eq('$id', projectId).delete();
    }
};

// =============================================
// Categories API (Level 3 - e.g., "Pipes", "Valves")
// =============================================
export const categoriesApi = {
    async listByProject(projectId) {
        const result = await db.from(COLLECTIONS.CATEGORIES)
            .select('*')
            .eq('project_id', projectId)
            .order('sort_order', { ascending: true })
            .exec();

        // 过滤掉已删除的分类（deleted_at 不为空）
        if (result.data) {
            result.data = result.data.filter(cat => !cat.deleted_at);
        }

        return result;
    },

    async create(projectId, name, sortOrder = 0) {
        const trimmedName = name.trim();

        // 检查同项目下是否已存在同名分类
        const existingResult = await db.from(COLLECTIONS.CATEGORIES)
            .select('*')
            .eq('project_id', projectId)
            .eq('name', trimmedName)
            .exec();

        if (existingResult.data && existingResult.data.length > 0) {
            return {
                data: null,
                error: new Error(`分类名称"${trimmedName}"已存在，请使用其他名称`)
            };
        }

        const data = {
            project_id: projectId,
            name: trimmedName,
            sort_order: sortOrder
        };

        try {
            return await db.from(COLLECTIONS.CATEGORIES).insert(data);
        } catch (error) {
            // 处理数据库唯一索引冲突（并发情况下可能发生）
            if (error?.message?.includes('already exists') || error?.code === 409) {
                return {
                    data: null,
                    error: new Error(`分类名称"${trimmedName}"已存在，请使用其他名称`)
                };
            }
            throw error;
        }
    },

    async update(categoryId, data) {
        return await db.from(COLLECTIONS.CATEGORIES).update(data).eq('$id', categoryId);
    },

    /**
     * 获取项目下所有分类的材料汇总数据
     * @param {string} projectId - 项目ID
     * @param {string} type - 'inbound' 或 'outbound'
     * @returns {Promise<{data: Array, error: Error|null}>}
     */
    async getCategorySummary(projectId, type = 'inbound') {
        try {
            // 获取项目下所有分类
            const categoriesResult = await this.listByProject(projectId);
            if (!categoriesResult.data || categoriesResult.data.length === 0) {
                return { data: [], error: null };
            }

            // 获取每个分类的材料数据
            const summaryData = await Promise.all(
                categoriesResult.data.map(async (category) => {
                    // 获取该分类下的所有材料
                    const materialsResult = await db.from(COLLECTIONS.MATERIALS)
                        .select('*')
                        .eq('category_id', category.$id)
                        .order('name', { ascending: true })
                        .exec();

                    const materials = (materialsResult.data || []).map(mat => ({
                        materialId: mat.$id,
                        name: mat.name || '',
                        specification: mat.specification || '',
                        material_type: mat.material_type || '',
                        // description 已移至 inbound_records/outbound_records
                        unit: mat.unit || '',
                        quantity: type === 'inbound' ? (mat.total_inbound || 0) : (mat.total_outbound || 0)
                    }));

                    return {
                        categoryId: category.$id,
                        categoryName: category.name,
                        materials,
                        sortOrder: category.sort_order || 0
                    };
                })
            );

            // 按 sortOrder 排序
            summaryData.sort((a, b) => a.sortOrder - b.sortOrder);

            return { data: summaryData, error: null };
        } catch (error) {
            return { data: null, error };
        }
    },

    async delete(categoryId) {
        // Delete all materials and records in this category first
        await materialsApi.deleteByCategory(categoryId);
        return await db.from(COLLECTIONS.CATEGORIES).eq('$id', categoryId).delete();
    },

    async deleteByProject(projectId) {
        const categories = await this.listByProject(projectId);
        if (categories.data) {
            for (const cat of categories.data) {
                await this.delete(cat.$id);
            }
        }
    },

    /**
     * 软删除分类（推荐使用）
     * 将分类标记为已删除，同时重命名避免唯一性冲突
     * 级联软删除该分类下所有材料
     * @param {string} categoryId - 分类ID
     * @returns {Promise<{data: any, error: Error|null}>}
     */
    async softDelete(categoryId) {
        try {
            // 1. 获取分类信息
            const categoryResult = await db.from(COLLECTIONS.CATEGORIES)
                .select('*')
                .eq('$id', categoryId)
                .single();

            if (!categoryResult.data) {
                return { data: null, error: new Error('分类不存在') };
            }

            const category = categoryResult.data;
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const deletedName = `${category.name}_已删除_${timestamp}`;

            // 2. 更新分类：设置 deleted_at 和重命名
            const updateResult = await db.from(COLLECTIONS.CATEGORIES)
                .update({
                    name: deletedName,
                    deleted_at: new Date().toISOString()
                })
                .eq('$id', categoryId);

            if (updateResult.error) {
                throw updateResult.error;
            }

            // 3. 级联软删除该分类下所有材料
            await materialsApi.softDeleteByCategory(categoryId);

            return { data: { categoryId, deletedName }, error: null };
        } catch (error) {
            console.error('Soft delete category error:', error);
            return { data: null, error };
        }
    }
};

// =============================================
// Materials API (Aggregate/Snapshot)
// =============================================
export const materialsApi = {
    async listByCategory(categoryId) {
        const result = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('category_id', categoryId)
            .order('name', { ascending: true })
            .exec();
        return result;
    },

    async listByProject(projectId) {
        const result = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('project_id', projectId)
            .order('name', { ascending: true })
            .exec();
        return result;
    },

    /**
     * Find existing material or create new one
     * Exact match required: name + specification + material_type
     */
    async findOrCreate(projectId, categoryId, materialData) {
        // Validate required fields
        if (!materialData.name || !materialData.specification || !materialData.material_type) {
            return {
                data: null,
                error: new Error('名称、规格型号和材质为必填项')
            };
        }

        const searchName = String(materialData.name).trim();
        const searchSpec = String(materialData.specification).trim();
        const searchType = String(materialData.material_type).trim();

        console.log('[findOrCreate] Searching for material:', {
            projectId,
            categoryId,
            name: searchName,
            specification: searchSpec,
            material_type: searchType
        });

        // 策略：先获取该分类下所有材料，然后本地精确匹配
        // 这样可以避免 Appwrite Query 对特殊字符（如双引号）的编码问题
        try {
            const allMaterials = await db.from(COLLECTIONS.MATERIALS)
                .select('*')
                .eq('category_id', categoryId)
                .exec();

            console.log('[findOrCreate] Category materials count:', allMaterials.data?.length || 0);

            if (allMaterials.data && allMaterials.data.length > 0) {
                // 本地精确匹配
                const found = allMaterials.data.find(mat =>
                    String(mat.name).trim() === searchName &&
                    String(mat.specification).trim() === searchSpec &&
                    String(mat.material_type).trim() === searchType
                );

                if (found) {
                    console.log('[findOrCreate] Found existing material with ID:', found.$id);
                    return { data: found, error: null, created: false };
                }
            }
        } catch (queryError) {
            console.error('[findOrCreate] Query error:', queryError);
        }

        // Not found, create new material
        console.log('[findOrCreate] Material not found, creating new one...');
        const newMaterial = {
            project_id: projectId,
            category_id: categoryId,
            name: searchName,
            specification: searchSpec,
            material_type: searchType,
            // description 已移至 inbound_records/outbound_records
            unit: materialData.unit || '',
            total_inbound: 0,
            total_outbound: 0,
            remaining_qty: 0
        };

        const result = await db.from(COLLECTIONS.MATERIALS).insert(newMaterial);
        return { ...result, created: true };
    },

    async updateTotals(materialId) {
        // Recalculate totals from records
        const inboundResult = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .select('quantity')
            .eq('material_id', materialId)
            .exec();

        const outboundResult = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .select('quantity')
            .eq('material_id', materialId)
            .exec();

        const totalInbound = (inboundResult.data || []).reduce((sum, r) => sum + (r.quantity || 0), 0);
        const totalOutbound = (outboundResult.data || []).reduce((sum, r) => sum + (r.quantity || 0), 0);
        const remainingQty = totalInbound - totalOutbound;

        return await db.from(COLLECTIONS.MATERIALS).update({
            total_inbound: totalInbound,
            total_outbound: totalOutbound,
            remaining_qty: remainingQty
        }).eq('$id', materialId);
    },

    /**
     * 更新材料信息（unit）
     * Note: description 已移至 inbound_records/outbound_records
     */
    async updateInfo(materialId, data) {
        const updateData = {};
        if (data.unit !== undefined) updateData.unit = data.unit;

        if (Object.keys(updateData).length === 0) return { data: null, error: null };
        return await db.from(COLLECTIONS.MATERIALS).update(updateData).eq('$id', materialId);
    },

    async deleteByCategory(categoryId) {
        // Delete all inbound/outbound records first
        const materials = await this.listByCategory(categoryId);
        if (materials.data) {
            for (const mat of materials.data) {
                await inboundRecordsApi.deleteByMaterial(mat.$id);
                await outboundRecordsApi.deleteByMaterial(mat.$id);
            }
        }
        return await db.from(COLLECTIONS.MATERIALS).eq('category_id', categoryId).delete();
    },

    /**
     * 软删除分类下所有材料
     * 将材料标记为已删除，同时重命名避免唯一性冲突
     * 注意：入库/出库记录保留，用于历史追溯
     * @param {string} categoryId - 分类ID
     */
    async softDeleteByCategory(categoryId) {
        const materials = await this.listByCategory(categoryId);
        if (materials.data) {
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            for (const mat of materials.data) {
                const deletedName = `${mat.name}_已删除_${timestamp}`;
                await db.from(COLLECTIONS.MATERIALS)
                    .update({
                        name: deletedName,
                        deleted_at: new Date().toISOString()
                    })
                    .eq('$id', mat.$id);
            }
        }
    }
};

// =============================================
// Inbound Records API
// =============================================
export const inboundRecordsApi = {
    async listByCategory(categoryId) {
        // Get all inbound records for this category
        const result = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .select('*')
            .eq('category_id', categoryId)
            .order('arrival_date', { ascending: false })
            .exec();

        if (!result.data || result.data.length === 0) {
            return result;
        }

        // Fetch material details for each record
        const recordsWithMaterials = await Promise.all(
            result.data.map(async (record) => {
                const materialResult = await db.from(COLLECTIONS.MATERIALS)
                    .select('*')
                    .eq('$id', record.material_id)
                    .single();

                const material = materialResult.data || {};

                // Merge record with material data (description 从 record 自身获取)
                return {
                    ...record,
                    name: material.name || '',
                    specification: material.specification || '',
                    material_type: material.material_type || '',
                    unit: material.unit || ''
                };
            })
        );

        return { data: recordsWithMaterials, error: null };
    },

    async listByMaterial(materialId) {
        const result = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .select('*')
            .eq('material_id', materialId)
            .order('arrival_date', { ascending: false })
            .exec();
        return result;
    },

    async create(projectId, categoryId, materialId, data) {
        const record = {
            project_id: projectId,
            category_id: categoryId,
            material_id: materialId,
            quantity: data.quantity,
            arrival_date: data.arrival_date,
            batch_no: data.batch_no || '',
            description: data.description || '',
            remarks: data.remarks || ''
        };

        const result = await db.from(COLLECTIONS.INBOUND_RECORDS).insert(record);

        // Update material totals
        if (result.data) {
            await materialsApi.updateTotals(materialId);
        }

        return result;
    },

    /**
     * Update inbound record
     * @param {string} recordId - 记录ID
     * @param {string} materialId - 材料ID
     * @param {object} data - 更新数据
     */
    async update(recordId, materialId, data) {
        const updateData = {};

        if (data.quantity !== undefined) updateData.quantity = data.quantity;
        if (data.arrival_date !== undefined) updateData.arrival_date = data.arrival_date;
        if (data.batch_no !== undefined) updateData.batch_no = data.batch_no;
        if (data.description !== undefined) updateData.description = data.description;
        if (data.remarks !== undefined) updateData.remarks = data.remarks;

        const result = await db.from(COLLECTIONS.INBOUND_RECORDS)
            .update(updateData)
            .eq('$id', recordId);

        // Recalculate totals
        if (!result.error) {
            await materialsApi.updateTotals(materialId);
        }

        return result;
    },

    async delete(recordId, materialId) {
        const result = await db.from(COLLECTIONS.INBOUND_RECORDS).eq('$id', recordId).delete();
        // Recalculate totals
        await materialsApi.updateTotals(materialId);
        return result;
    },

    async deleteByMaterial(materialId) {
        return await db.from(COLLECTIONS.INBOUND_RECORDS).eq('material_id', materialId).delete();
    }
};

// =============================================
// Outbound Records API
// =============================================
export const outboundRecordsApi = {
    async listByCategory(categoryId) {
        // Get all outbound records for this category
        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .select('*')
            .eq('category_id', categoryId)
            .order('outbound_date', { ascending: false })
            .exec();

        if (!result.data || result.data.length === 0) {
            return result;
        }

        // Fetch material details for each record
        const recordsWithMaterials = await Promise.all(
            result.data.map(async (record) => {
                const materialResult = await db.from(COLLECTIONS.MATERIALS)
                    .select('*')
                    .eq('$id', record.material_id)
                    .single();

                const material = materialResult.data || {};

                // Merge record with material data (description 从 record 自身获取)
                return {
                    ...record,
                    name: material.name || '',
                    specification: material.specification || '',
                    material_type: material.material_type || '',
                    unit: material.unit || ''
                };
            })
        );

        return { data: recordsWithMaterials, error: null };
    },

    async listByMaterial(materialId) {
        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .select('*')
            .eq('material_id', materialId)
            .order('outbound_date', { ascending: false })
            .exec();
        return result;
    },

    /**
     * Create outbound record with stock validation
     */
    async create(projectId, categoryId, materialId, data) {
        // First, check remaining stock
        const material = await db.from(COLLECTIONS.MATERIALS)
            .select('*')
            .eq('$id', materialId)
            .single();

        if (!material.data) {
            return { data: null, error: new Error('Material not found') };
        }

        const remainingQty = material.data.remaining_qty || 0;
        if (data.quantity > remainingQty) {
            return {
                data: null,
                error: new Error(`库存不足！剩余: ${remainingQty}, 请求: ${data.quantity}`)
            };
        }

        const record = {
            project_id: projectId,
            category_id: categoryId,
            material_id: materialId,
            quantity: data.quantity,
            outbound_date: data.outbound_date,
            outbound_no: data.outbound_no || '',
            description: data.description || '',
            remarks: data.remarks || ''
        };

        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS).insert(record);

        // Update material totals
        if (result.data) {
            await materialsApi.updateTotals(materialId);
        }

        return result;
    },

    /**
     * Update outbound record with stock validation
     * @param {string} recordId - 记录ID
     * @param {string} materialId - 材料ID
     * @param {object} data - 更新数据
     */
    async update(recordId, materialId, data) {
        // 如果修改了数量，需要验证库存
        if (data.quantity !== undefined) {
            // 获取当前记录的原始数量
            const currentRecord = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
                .select('quantity')
                .eq('$id', recordId)
                .single();

            if (!currentRecord.data) {
                return { data: null, error: new Error('记录不存在') };
            }

            const oldQuantity = currentRecord.data.quantity || 0;
            const newQuantity = data.quantity;
            const quantityDiff = newQuantity - oldQuantity; // 正数表示增加出库量

            // 只有增加出库量时才需要检查库存
            if (quantityDiff > 0) {
                const material = await db.from(COLLECTIONS.MATERIALS)
                    .select('remaining_qty')
                    .eq('$id', materialId)
                    .single();

                if (!material.data) {
                    return { data: null, error: new Error('材料不存在') };
                }

                const remainingQty = material.data.remaining_qty || 0;

                // 检查剩余库存是否足够支撑增量
                if (quantityDiff > remainingQty) {
                    return {
                        data: null,
                        error: new Error(`库存不足！当前剩余: ${remainingQty}，需要增加: ${quantityDiff}`)
                    };
                }
            }
        }

        const updateData = {};
        if (data.quantity !== undefined) updateData.quantity = data.quantity;
        if (data.outbound_date !== undefined) updateData.outbound_date = data.outbound_date;
        if (data.outbound_no !== undefined) updateData.outbound_no = data.outbound_no;
        if (data.description !== undefined) updateData.description = data.description;
        if (data.remarks !== undefined) updateData.remarks = data.remarks;

        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS)
            .update(updateData)
            .eq('$id', recordId);

        // Recalculate totals
        if (!result.error) {
            await materialsApi.updateTotals(materialId);
        }

        return result;
    },

    async delete(recordId, materialId) {
        const result = await db.from(COLLECTIONS.OUTBOUND_RECORDS).eq('$id', recordId).delete();
        // Recalculate totals
        await materialsApi.updateTotals(materialId);
        return result;
    },

    async deleteByMaterial(materialId) {
        return await db.from(COLLECTIONS.OUTBOUND_RECORDS).eq('material_id', materialId).delete();
    }
};

// =============================================
// Users API (for admin management)
// 权限控制基于users集合的role字段
// =============================================
export const usersApi = {
    async list() {
        const result = await db.from(COLLECTIONS.USERS)
            .select('*')
            .order('created_at', { ascending: false })
            .exec();
        return result;
    },

    async create(email, username, password, role = 'observer') {
        const { auth, db } = await import('../providers/index.js');
        const { config } = await import('../config.js');

        try {
            // Create Appwrite auth user
            const { data: authData, error: authError } = await auth.signUp(
                email,
                password,
                { username }
            );

            if (authError) {
                return { data: null, error: authError };
            }

            // Create user profile in users collection
            // IMPORTANT: Use the same ID as the auth user
            const userId = authData.user.$id || authData.user.id;

            // Get direct access to Appwrite databases
            const databases = db.getDatabase();
            const databaseId = config.APPWRITE_DATABASE_ID || 'bmms';

            try {
                // Create document with specific ID (same as auth user ID)
                const userDoc = await databases.createDocument(
                    databaseId,
                    COLLECTIONS.USERS,
                    userId,
                    {
                        email,
                        username,
                        role
                    }
                );

                // 自动验证用户邮箱（设置 Status 为 Verified）
                try {
                    await this.verifyEmail(userId);
                    console.log('[usersApi.create] Email verified for user:', userId);
                } catch (verifyError) {
                    // 验证失败不阻塞用户创建，只记录警告
                    console.warn('[usersApi.create] Failed to verify email, user created but unverified:', verifyError.message);
                }

                return { data: userDoc, error: null };
            } catch (dbError) {
                console.error('Failed to create user profile:', dbError);
                return {
                    data: null,
                    error: new Error(`User auth created but profile failed: ${dbError.message}`)
                };
            }
        } catch (error) {
            console.error('Create user error:', error);
            return { data: null, error };
        }
    },

    async updateRole(userId, newRole) {
        // 直接更新数据库中的角色
        return await db.from(COLLECTIONS.USERS).update({ role: newRole }).eq('$id', userId);
    },

    /**
     * 管理员修改用户密码
     * 支持两种模式：
     * - api_key: 直接调用 Appwrite REST API（需要在前端配置 API Key，不推荐生产环境使用）
     * - function: 调用 Appwrite Cloud Function（推荐，API Key 存储在服务端）
     * 
     * @param {string} userId - 用户ID
     * @param {string} newPassword - 新密码
     * @returns {Promise<{data: any, error: Error|null}>}
     */
    async updatePassword(userId, newPassword) {
        const { config } = await import('../config.js');

        const mode = config.APPWRITE_PASSWORD_MODE || 'api_key';
        const endpoint = config.APPWRITE_URL;
        const projectId = config.APPWRITE_PROJECT_ID;

        try {
            if (mode === 'function') {
                // Function 模式：调用 Appwrite Cloud Function
                return await this._updatePasswordViaFunction(userId, newPassword, endpoint, projectId, config);
            } else {
                // API Key 模式：直接调用 REST API
                return await this._updatePasswordViaApiKey(userId, newPassword, endpoint, projectId, config);
            }
        } catch (error) {
            console.error('Update password error:', error);
            return { data: null, error };
        }
    },

    /**
     * 通过 API Key 直接调用 Appwrite REST API 修改密码
     */
    async _updatePasswordViaApiKey(userId, newPassword, endpoint, projectId, config) {
        const apiKey = config.APPWRITE_API_KEY;

        if (!apiKey) {
            return {
                data: null,
                error: new Error('管理员API密钥未配置，无法修改用户密码。请联系系统管理员配置 APPWRITE_API_KEY。')
            };
        }

        const response = await fetch(`${endpoint}/users/${userId}/password`, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId,
                'X-Appwrite-Key': apiKey
            },
            body: JSON.stringify({ password: newPassword })
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `修改密码失败 (${response.status})`);
        }

        const data = await response.json();
        return { data, error: null };
    },

    /**
     * 通过 Appwrite Cloud Function 修改密码
     */
    async _updatePasswordViaFunction(userId, newPassword, endpoint, projectId, config) {
        const functionId = config.APPWRITE_FUNCTION_USER_MANAGEMENT;

        if (!functionId) {
            return {
                data: null,
                error: new Error('Function ID 未配置，无法修改用户密码。请联系系统管理员配置 APPWRITE_FUNCTION_USER_MANAGEMENT。')
            };
        }

        console.log('[updatePassword] Calling function:', functionId);

        // 调用 Appwrite Function 执行端点
        const response = await fetch(`${endpoint}/functions/${functionId}/executions`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId
            },
            body: JSON.stringify({
                body: JSON.stringify({ userId, newPassword }),
                async: false
            })
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            console.error('[updatePassword] Function call failed:', errorData);
            throw new Error(errorData.message || `调用 Function 失败 (${response.status})`);
        }

        const execution = await response.json();
        console.log('[updatePassword] Execution result:', execution);

        // 解析 Function 返回的结果
        if (execution.status === 'completed') {
            try {
                const result = JSON.parse(execution.responseBody || '{}');
                if (result.success) {
                    return { data: result, error: null };
                } else {
                    throw new Error(result.message || '修改密码失败');
                }
            } catch (parseError) {
                console.error('[updatePassword] Parse error:', parseError, 'ResponseBody:', execution.responseBody);
                throw new Error('Function 返回数据解析失败');
            }
        } else {
            // 提取更详细的错误信息
            const errorDetails = execution.errors || execution.logs || execution.stderr || '';
            console.error('[updatePassword] Function failed:', execution.status, 'Details:', errorDetails);
            throw new Error(`Function 执行失败: ${execution.status}${errorDetails ? ' - ' + errorDetails : ''}`);
        }
    },

    /**
     * 验证用户邮箱（将 Status 设置为 Verified）
     * 通过 Appwrite Cloud Function 执行，避免在前端暴露 API Key
     * 
     * @param {string} userId - 用户ID
     * @returns {Promise<{data: any, error: Error|null}>}
     */
    async verifyEmail(userId) {
        const { config } = await import('../config.js');

        const mode = config.APPWRITE_PASSWORD_MODE || 'api_key';
        const endpoint = config.APPWRITE_URL;
        const projectId = config.APPWRITE_PROJECT_ID;

        try {
            if (mode === 'function') {
                // Function 模式：调用 Appwrite Cloud Function
                return await this._callUserFunction('verifyEmail', { userId }, endpoint, projectId, config);
            } else {
                // API Key 模式：直接调用 REST API
                return await this._verifyEmailViaApiKey(userId, endpoint, projectId, config);
            }
        } catch (error) {
            console.error('Verify email error:', error);
            return { data: null, error };
        }
    },

    /**
     * 通过 API Key 直接调用 Appwrite REST API 验证邮箱
     */
    async _verifyEmailViaApiKey(userId, endpoint, projectId, config) {
        const apiKey = config.APPWRITE_API_KEY;

        if (!apiKey) {
            return {
                data: null,
                error: new Error('管理员API密钥未配置，无法验证用户邮箱。请联系系统管理员配置 APPWRITE_API_KEY。')
            };
        }

        const response = await fetch(`${endpoint}/users/${userId}/verification`, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId,
                'X-Appwrite-Key': apiKey
            },
            body: JSON.stringify({ emailVerification: true })
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `验证邮箱失败 (${response.status})`);
        }

        const data = await response.json();
        return { data, error: null };
    },

    /**
     * 通用方法：调用 Appwrite Cloud Function 执行用户管理操作
     * @param {string} action - 操作类型: 'updatePassword' | 'verifyEmail'
     * @param {object} params - 操作参数
     * @param {string} endpoint - Appwrite 端点
     * @param {string} projectId - 项目ID
     * @param {object} config - 配置对象
     */
    async _callUserFunction(action, params, endpoint, projectId, config) {
        const functionId = config.APPWRITE_FUNCTION_USER_MANAGEMENT;

        if (!functionId) {
            return {
                data: null,
                error: new Error('Function ID 未配置。请联系系统管理员配置 APPWRITE_FUNCTION_USER_MANAGEMENT。')
            };
        }

        console.log(`[_callUserFunction] Calling function for action: ${action}`);

        const response = await fetch(`${endpoint}/functions/${functionId}/executions`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId
            },
            body: JSON.stringify({
                body: JSON.stringify({ action, ...params }),
                async: false
            })
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            console.error(`[_callUserFunction] Function call failed:`, errorData);
            throw new Error(errorData.message || `调用 Function 失败 (${response.status})`);
        }

        const execution = await response.json();
        console.log(`[_callUserFunction] Execution result:`, execution);

        if (execution.status === 'completed') {
            try {
                const result = JSON.parse(execution.responseBody || '{}');
                if (result.success) {
                    return { data: result, error: null };
                } else {
                    throw new Error(result.message || '操作失败');
                }
            } catch (parseError) {
                console.error(`[_callUserFunction] Parse error:`, parseError, 'ResponseBody:', execution.responseBody);
                throw new Error('Function 返回数据解析失败');
            }
        } else {
            const errorDetails = execution.errors || execution.logs || execution.stderr || '';
            console.error(`[_callUserFunction] Function failed:`, execution.status, 'Details:', errorDetails);
            throw new Error(`Function 执行失败: ${execution.status}${errorDetails ? ' - ' + errorDetails : ''}`);
        }
    },

    /**
     * 删除用户（同时删除 Auth 用户和 users 集合文档）
     * @param {string} userId - 用户ID
     * @returns {Promise<{data: any, error: Error|null}>}
     */
    async delete(userId) {
        const { config } = await import('../config.js');

        const mode = config.APPWRITE_PASSWORD_MODE || 'api_key';
        const endpoint = config.APPWRITE_URL;
        const projectId = config.APPWRITE_PROJECT_ID;

        try {
            // 1. 先删除 Auth 用户
            if (mode === 'function') {
                // Function 模式：调用 Appwrite Cloud Function
                await this._callUserFunction('deleteUser', { userId }, endpoint, projectId, config);
            } else {
                // API Key 模式：直接调用 REST API
                await this._deleteAuthUserViaApiKey(userId, endpoint, projectId, config);
            }
            console.log('[usersApi.delete] Auth user deleted:', userId);
        } catch (authError) {
            // Auth 用户删除失败，记录警告但继续删除 users 集合文档
            console.warn('[usersApi.delete] Failed to delete auth user:', authError.message);
        }

        // 2. 删除 users 集合中的文档
        const result = await db.from(COLLECTIONS.USERS).eq('$id', userId).delete();
        return result;
    },

    /**
     * 通过 API Key 直接调用 Appwrite REST API 删除 Auth 用户
     */
    async _deleteAuthUserViaApiKey(userId, endpoint, projectId, config) {
        const apiKey = config.APPWRITE_API_KEY;

        if (!apiKey) {
            throw new Error('管理员API密钥未配置，无法删除Auth用户。请联系系统管理员配置 APPWRITE_API_KEY。');
        }

        const response = await fetch(`${endpoint}/users/${userId}`, {
            method: 'DELETE',
            headers: {
                'Content-Type': 'application/json',
                'X-Appwrite-Project': projectId,
                'X-Appwrite-Key': apiKey
            }
        });

        if (!response.ok) {
            const errorData = await response.json().catch(() => ({}));
            throw new Error(errorData.message || `删除Auth用户失败 (${response.status})`);
        }

        return { success: true };
    }
};
